fn has_only_one_distinct_element(a: &[i32]) -> bool {
    // An empty slice or a single-element slice trivially has only one distinct value.
    if let Some((&first, rest)) = a.split_first() {
        // Check that every other element equals the first one.
        rest.iter().all(|&x| x == first)
    } else {
        true
    }
}

